-- compare_xs.tsv: for each literal, how many rows of tx `xs <op> <literal>` keeps, the
-- sum of their id, and how many rows DuckDB cannot decide (the comparison raises a
-- conversion error: TRY gives NULL for a row whose xs is not NULL), for each of the six
-- comparison operators. The literal is the SQL text the test runs too (a folded bound is
-- written as the arithmetic), so the file holds DuckDB's reading of it. NULL rows are in
-- neither the kept rows nor their complement. Column xs is DECIMAL(15, 2) and holds +-9999999999999.99.
COPY (
SELECT * FROM (
  SELECT 0 AS n, 'xs' AS col, '0.06' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 0.06)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 0.06)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 0.06) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 0.06)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 0.06)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 0.06) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 0.06)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 0.06)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 0.06) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 0.06)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 0.06)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 0.06) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 0.06)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 0.06)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 0.06) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 0.06)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 0.06)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 0.06) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 1 AS n, 'xs' AS col, '0.0000000000000000000000001' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 0.0000000000000000000000001)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 0.0000000000000000000000001)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 0.0000000000000000000000001)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 0.0000000000000000000000001)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 0.0000000000000000000000001)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 0.0000000000000000000000001)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 0.0000000000000000000000001)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 0.0000000000000000000000001)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 0.0000000000000000000000001)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 0.0000000000000000000000001)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 0.0000000000000000000000001)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 0.0000000000000000000000001)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 0.0000000000000000000000001) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 2 AS n, 'xs' AS col, '0.00000000000000000000000001' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 0.00000000000000000000000001)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 0.00000000000000000000000001)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 0.00000000000000000000000001)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 0.00000000000000000000000001)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 0.00000000000000000000000001)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 0.00000000000000000000000001)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 0.00000000000000000000000001)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 0.00000000000000000000000001)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 0.00000000000000000000000001)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 0.00000000000000000000000001)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 0.00000000000000000000000001)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 0.00000000000000000000000001)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 0.00000000000000000000000001) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 3 AS n, 'xs' AS col, '9999999999999.99' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 9999999999999.99)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 9999999999999.99)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 9999999999999.99) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 9999999999999.99)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 9999999999999.99)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 9999999999999.99) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 9999999999999.99)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 9999999999999.99)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 9999999999999.99) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 9999999999999.99)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 9999999999999.99)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 9999999999999.99) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 9999999999999.99)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 9999999999999.99)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 9999999999999.99) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 9999999999999.99)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 9999999999999.99)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 9999999999999.99) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 4 AS n, 'xs' AS col, '9999999999999.995' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 9999999999999.995)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 9999999999999.995)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 9999999999999.995) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 9999999999999.995)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 9999999999999.995)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 9999999999999.995) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 9999999999999.995)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 9999999999999.995)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 9999999999999.995) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 9999999999999.995)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 9999999999999.995)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 9999999999999.995) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 9999999999999.995)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 9999999999999.995)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 9999999999999.995) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 9999999999999.995)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 9999999999999.995)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 9999999999999.995) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 5 AS n, 'xs' AS col, '-9999999999999.995' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < -9999999999999.995)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < -9999999999999.995)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < -9999999999999.995) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= -9999999999999.995)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= -9999999999999.995)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= -9999999999999.995) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > -9999999999999.995)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > -9999999999999.995)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > -9999999999999.995) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= -9999999999999.995)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= -9999999999999.995)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= -9999999999999.995) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = -9999999999999.995)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = -9999999999999.995)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = -9999999999999.995) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> -9999999999999.995)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> -9999999999999.995)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> -9999999999999.995) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 6 AS n, 'xs' AS col, '10000000000000000' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 10000000000000000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 10000000000000000)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 10000000000000000) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 10000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 10000000000000000)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 10000000000000000) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 10000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 10000000000000000)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 10000000000000000) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 10000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 10000000000000000)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 10000000000000000) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 10000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 10000000000000000)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 10000000000000000) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 10000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 10000000000000000)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 10000000000000000) IS NULL AND xs IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 7 AS n, 'xs' AS col, '1000000000000000000000000000000000000' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xs < 1000000000000000000000000000000000000)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs < 1000000000000000000000000000000000000)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xs < 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <= 1000000000000000000000000000000000000)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <= 1000000000000000000000000000000000000)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xs <= 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xs > 1000000000000000000000000000000000000)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs > 1000000000000000000000000000000000000)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xs > 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xs >= 1000000000000000000000000000000000000)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs >= 1000000000000000000000000000000000000)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xs >= 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xs = 1000000000000000000000000000000000000)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs = 1000000000000000000000000000000000000)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xs = 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xs <> 1000000000000000000000000000000000000)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xs <> 1000000000000000000000000000000000000)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xs <> 1000000000000000000000000000000000000) IS NULL AND xs IS NOT NULL) AS ne_e
) AS q ORDER BY n
) TO 'compare_xs.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
